#!/usr/bin/env python3
from pathlib import Path
import sys,json,html,hashlib
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'manual'))
from content import PAGES
O=R/'dist/manual';O.mkdir(exist_ok=True)
sections=[]
def add(id,title,body,group='Tocar'):
 sections.append((id,title,body,group))
def table(head,rows):
 return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(text):return '<aside class="note">'+text+'</aside>'
def shot(name,alt,caption=''):
 return f'<figure class="screen-figure"><button class="screen-zoom" data-screen="{name}" aria-label="Ampliar tela {html.escape(alt)}"><img src="images/{name}-light.png" data-capture="{name}" width="240" height="240" loading="lazy" alt="{html.escape(alt)}"></button><figcaption>{caption or alt} <span>Toque para ampliar</span></figcaption></figure>'
add('comecar','Comece a tocar', '''<p class="lead">Uma fita para a melodia. Outra para acompanhar. O SMKTRON transforma o SMK-37 Pro em um instrumento de fitas inspirado no Mellotron, com camadas, efeitos, padrões e acordes nos pads.</p>
<div class="stats"><div><b>4</b><span>timbres de fita</span></div><div><b>8</b><span>cenas e acordes</span></div><div><b>16</b><span>passos de sequência</span></div></div>
<ol class="steps"><li><b>Comece pelo volume.</b> Ajuste K5 para a cena. Se precisar reduzir toda a saída para fones ou amplificador, use GLOBE → SYSTEM → K3 MASTER.</li><li><b>Escolha uma fita.</b> Pressione PATCH e um dos pads 1–4, ou gire K8: FLUTE, CHOIR, CELLO ou VIOLINS.</li><li><b>Modele o som.</b> K1–K4 seguem os quatro parâmetros mostrados na parte inferior da tela. Experimente TONE e RELEASE em PLAY.</li><li><b>Adicione profundidade.</b> SCALE abre LAYER; FX percorre os efeitos; NOTE REPEAT abre TAPE/WEAR.</li><li><b>Guarde o ponto de partida.</b> Um toque breve em SAVE/BT salva o estado de inicialização. Para guardar uma cena em um dos oito slots, veja <a href="#presets">Cenas e presets</a>.</li></ol>
'''+note('A força da tecla não regula o volume como em um piano: o SMKTRON usa nível de nota fixo, coerente com a proposta de fita. Use K5, Master e os controles de mistura para equilibrar a execução.'))
controls=[['PATCH','Abre PLAY; em PLAY, avança o timbre.','—'],['SCALE','Abre LAYER; em LAYER, avança SOUND.','Durante SEQ REC parado: segurar ~1 s limpa o padrão.'],['NOTE REPEAT','Acessa TAPE / WEAR.','~0,6 s: bypass de LOFI.'],['FX','Percorre VIBRATO / LESLIE / ECHO / REVERB.','~0,6 s: bypass geral de FX, com caudas.'],['PARA','Abre EQ.','~0,6 s: restaura EQ plano.'],['GLOBE','Percorre SETUP / SYSTEM / PAD CHORDS.','—'],['CHORD','Alterna o HOLD do teclado ao soltar.','~0,6 s: alterna HALF SPEED.'],['ARP','Ativa e abre ARP; nessa página, alterna ON/OFF.','—'],['SEQ','Abre a página de sequência.','—'],['SEQ PLAY','Inicia ou interrompe a sequência.','—'],['SEQ REC','Liga ou desliga a gravação da sequência.','—'],['SAVE / BT','Salva o estado de boot ao soltar um toque breve.','~0,6 s: abre o acesso às cenas.'],['OCT − / +','Transpõe o teclado de −2 a +2 oitavas.','—'],['← / →','Percorrem todas as páginas, em sequência.','—'],['FADER BANK','Troca os bancos A/B dos quatro faders.','A luz indica o banco B.'],['KNOB BANK','—','Mantém a tela de diagnóstico do painel aberta.']]
add('painel','Painel e navegação','''<p>Os nomes impressos no SMK-37 nem sempre descrevem a função musical usada pelo firmware. Esta é a referência do painel.</p>
<div class="knob-map">'''+''.join(f'<div><b>K{i}</b><span>{label}</span></div>' for i,label in enumerate(['Parâmetro 1','Parâmetro 2','Parâmetro 3','Parâmetro 4','Volume da cena','Páginas da seção','Tempo / BPM','Timbre principal'],1))+'''</div>
<p><b>K1–K4</b> sempre correspondem aos controles no rodapé do display. <b>K6</b> alterna páginas da seção atual; as setas percorrem todas as seções. <b>K7</b> muda o BPM em qualquer tela e <b>K8</b> muda o timbre principal. Giros rápidos dos encoders podem acelerar o ajuste.</p>'''+table(['Botão','Toque breve','Pressionar e manter / observação'],controls)+
'<p class="small">Unidades: <b>st</b> = semitons; <b>ct</b> = cents (100 ct = 1 semitom); <b>ms</b> = milissegundos; <b>Hz</b> = ciclos por segundo. GATE é a duração da nota dentro do passo.</p><h3>Faders: dois bancos, quatro controles</h3>'+table(['Fader','Banco A','Banco B'],[['1','MIX do layer','AGE'],['2','TONE','DRIVE de TAPE'],['3','WOW','MIX de ECHO'],['4','FLUTTER','MIX de REVERB']])+
'<p>Depois de iniciar ou trocar de banco, cada fader só atua quando é movido. Isso evita uma alteração imediata ao trocar de banco, mas não é um sistema de captura por cruzamento: ao mover, o parâmetro acompanha sua posição física. No modo Chord, o MIX entre melodia e pads é o K1 de PAD CHORDS; o Fader 1 do banco A continua ligado ao MIX do layer.</p><p><b>Pitch wheel:</b> varia a velocidade e a afinação em aproximadamente ±2 semitons. <b>Mod wheel:</b> acrescenta vibrato. <b>HALF SPEED:</b> reduz a velocidade à metade e leva as fitas uma oitava abaixo, com uma transição gradual.</p>'+note('O botão físico CHORD alterna o HOLD do teclado; ele não abre PAD CHORDS. Com esse HOLD ligado, as notas continuam após soltar as teclas e o próximo conjunto substitui o anterior. Desligá-lo libera as notas retidas por esse HOLD. O HOLD dos pads, no pad 10 do modo de acordes, é independente.'))
add('pads','Três mapas para os pads','''<p>Os 16 pads mudam de função conforme o modo ativo. A linha superior tem pads 1–8; a inferior, 9–16. Escolha um mapa para consultar:</p>
<div class="pad-tabs" role="group" aria-label="Mapa de pads"><button data-map="normal" aria-pressed="true">Normal</button><button data-map="presets" aria-pressed="false">Cenas / presets</button><button data-map="chords" aria-pressed="false">Pad Chords</button></div>
<p id="pad-description" aria-live="polite"></p><div id="pad-map" class="pad-map"></div><p class="small">Diagrama de consulta: estes pads não controlam o teclado. As cores são extraídas da engine; sua aparência física depende do brilho escolhido e dos LEDs.</p>
<h3>No mapa normal</h3>'''+table(['Pads','Função'],[['1–4','Timbre principal: FLUTE, CHOIR, CELLO, VIOLINS.'],['5–8','Layer: os mesmos quatro timbres. Pressionar o já selecionado desliga o layer.'],['9','LOFI: liga / bypass.'],['10','VIBRATO: liga / desliga pelo MIX.'],['11','LESLIE: liga / desliga pelo MIX.'],['12','LESLIE FAST / SLOW.'],['13','ECHO: liga / desliga pelo MIX.'],['14','REVERB: liga / desliga pelo MIX.'],['15','HALF SPEED.'],['16','LENGTH: 8 SEC / HELD.']])+note('O pad de efeito desliga o MIX e pode recuperar o valor memorizado ao religar na mesma sessão. O bypass geral de FX é outro controle: segure FX para retirar o grupo sem zerar todos os ajustes.'))
for id,title,image,description,access,knobs,detail in PAGES:
 add(id,title,'<div class="page-intro">'+shot(image,title)+'<div><p class="lead">'+description+'</p><div class="access"><b>Como acessar</b><p>'+access+'</p></div><p>'+detail+'</p></div></div>'+table(['Controle','Na tela','Faixa','O que faz'],knobs),'Editar' if id not in ['chords','arp','seq'] else 'Tocar')
add('gravar-acordes','Grave e toque seus acordes','''<ol class="steps"><li><b>Ative o modo.</b> GLOBE até PAD CHORDS e K4 MODE em ON. Os pads superiores mudam para rosa/lilás.</li><li><b>Arme a gravação.</b> Pressione o pad 9, REC. O acorde em reprodução é liberado.</li><li><b>Escolha o destino.</b> Toque um pad de 1 a 8. Ele pisca em rosa claro enquanto espera o acorde.</li><li><b>Toque nas teclas.</b> Monte o acorde ou a inversão desejada, com até seis notas distintas. O teclado continua audível.</li><li><b>Solte todas as teclas.</b> O acorde é gravado globalmente e REC desliga. Não é necessário apertar SAVE.</li><li><b>Escolha a fita dos pads.</b> Pads 11–14: FLUTE, CHOIR, CELLO e VIOLINS. Essa escolha vale para o banco todo.</li><li><b>Toque o acorde.</b> Sem HOLD, solte o pad para liberar. Com HOLD (pad 10), solte o pad e continue tocando a melodia.</li></ol>
<h3>Substituir, interromper e sair</h3><p>Um novo pad de acorde <b>substitui</b> o anterior, com ou sem HOLD: este modo toca um acorde por vez. Soltar um pad anterior não corta o novo. Desligar HOLD libera o acorde sustentado. O pad 15 faz STOP e cancela a gravação; ele não apaga o banco nem funciona como STOP do sequenciador. O pad 16 sai do modo.</p>
<p>Para regravar um slot, repita REC → destino → acorde → solte as teclas. Mais de seis notas distintas cancela a tomada, preserva o conteúdo anterior e permite tentar outra vez. Evite deixar SEQ REC ligado quando a intenção for gravar apenas um acorde nos pads.</p>
<h3>Como ler as luzes</h3>'''+table(['Estado','Indicação'],[['Slot vazio','Lilás bem escuro.'],['Acorde gravado','Lilás intermediário.'],['Pad de acorde ativo','Rosa forte; permanece destacado com HOLD.'],['Destino de REC','Rosa claro piscando.'],['Pad 9 / REC','Vermelho forte quando armado; fraco quando desligado.'],['Pad 10 / HOLD','Laranja forte quando ligado; fraco quando desligado.'],['Pads 11–14 / fitas','Verde, roxo, laranja e azul. O selecionado fica forte; os demais, fracos.'],['Pad 15 / STOP','Vermelho discreto.'],['Pad 16 / sair','Branco discreto.']])+note('Os pads guardam notas, não gravações de áudio. Não há um timbre ou uma cadeia de efeitos diferente para cada slot: os oito acordes usam a fita global escolhida. Para sustain contínuo, prefira LENGTH HELD.'))
add('interacao','Teclado, acordes, ARP e SEQ','''<p>O modo Chord divide os recursos em dois grupos, mantendo a melodia independente dos pads.</p>'''+table(['Situação','Grupo da melodia','Grupo dos acordes'],[['MODE OFF','12 vozes para o funcionamento normal, incluindo layer.','Sem reserva exclusiva para pads.'],['MODE ON','6 vozes compartilhadas por teclado, ARP e SEQ.','6 vozes para o acorde ativo.'],['PLAY do sequenciador','A sequência usa o timbre principal e o PAN MEL.','O acorde dos pads, inclusive em HOLD, continua independente.'],['ARP ligado','Arpeja as notas recebidas do teclado/MIDI.','Os acordes dos pads continuam inteiros.'],['STOP de SEQ / ARP','Interrompe a respectiva fonte da melodia.','Não libera o HOLD dos pads.']])+'''<p>Uma sequência cheia somada ao teclado pode exigir substituição de notas mais antigas dentro das seis vozes da melodia. O grupo dos acordes permanece reservado. MIX e os pans de PAD CHORDS regulam os dois grupos; os controles de tom, envelope, afinação, volume e os efeitos são compartilhados.</p>
<p>As notas dos acordes são armazenadas nas alturas tocadas. Mudar PITCH ou os botões OCT depois não reescreve o banco; TUNE, pitch wheel e HALF SPEED continuam afetando a reprodução dos dois grupos.</p><p>O pan posiciona o sinal antes dos efeitos. Delay e reverb retornam em ambos os canais; vibrato e Leslie também compartilham processamento. Portanto, pan totalmente à esquerda não promete silêncio absoluto à direita quando esses efeitos estão presentes.</p>'''+note('Trocar de tela não troca o modo. Abrir PATCH com MODE ON mantém 6 + 6 vozes. Somente MODE OFF devolve as 12 vozes ao funcionamento normal. Ao abrir o acesso às cenas, o modo Chord é encerrado.'))
add('gravar-seq','Grave uma sequência','''<h3>Por passos, com o transporte parado</h3><ol class="steps"><li>Pressione SEQ e confira que SEQ PLAY está parado.</li><li>Ative SEQ REC.</li><li>Toque uma nota ou acorde de até quatro notas; solte todas as teclas para avançar ao próximo passo.</li><li>Para inserir uma pausa, pressione SCALE sem tocar notas.</li><li>Desative SEQ REC e pressione SEQ PLAY para ouvir. Ajuste LENGTH, GATE, SWING e BPM.</li></ol>
<h3>Durante a reprodução</h3><p>Com SEQ PLAY ativo, ligue SEQ REC e toque. As notas entram no passo correspondente ao momento da execução. Desligue REC para parar de acrescentar notas; PLAY continua o padrão.</p>
<h3>Editar ou limpar</h3><p>Com a sequência parada, use K3 STEP para escolher a posição. Com REC ligado, a primeira nota de uma nova entrada substitui o conteúdo daquele passo. Durante SEQ REC parado, mantenha SCALE por aproximadamente um segundo para limpar o padrão inteiro.</p>'''+note('O botão <b>SEQ REC</b> grava a sequência de 16 passos. O <b>pad 9 REC</b> no modo Chord grava um acorde global. São gravadores diferentes. Salve a sequência com SAVE breve para o boot ou junto de uma cena.'))
add('presets','Cenas e presets','''<div class="page-intro">'''+shot('presets','Acesso às cenas no display','Tela real com o acesso aos presets fixado')+'''<div><p class="lead">Oito memórias para recuperar timbres, combinações, efeitos e padrões durante a execução.</p><p>Cena e preset são os mesmos oito slots musicais neste manual. Eles são independentes do SAVE de inicialização e do banco global de acordes.</p></div></div>
<ol class="steps"><li><b>Abra as cenas:</b> segure SAVE/BT por cerca de 0,6 s e mantenha pressionado.</li><li><b>Carregue:</b> toque brevemente um pad superior de 1 a 8. Um slot vazio não altera o som.</li><li><b>Grave:</b> mantenha um pad superior por aproximadamente 1 s. O estado musical atual substitui o conteúdo daquele slot.</li><li><b>Fixe o acesso:</b> pressione o pad 9 amarelo enquanto as cenas estiverem abertas. Solte SAVE: os pads continuam no modo de presets.</li><li><b>Saia:</b> pressione novamente o pad 9 para liberar o acesso fixado. Sem fixar, basta soltar SAVE.</li></ol>
<p>O último preset <b>carregado com sucesso</b> tem verde distinto e pulsação suave de 1,8 s. Salvar outro slot não transfere esse indicador; tentar carregar um slot vazio também não. Durante a gravação, há progresso de iluminação e confirmação breve.</p>
<h3>O que a cena guarda</h3><p>Timbres, layer, ajustes de som, efeitos, EQ, afinação/transposição, tempo, LENGTH/SCREEN, HALF SPEED, padrão do sequenciador, parâmetros de ARP/SEQ, volume K5 e banco de faders. Ela não guarda a execução em andamento nem os acordes globais.</p>
<p>Carregar uma cena interrompe o sequenciador; os parâmetros de ARP são recuperados, sem transformar seu estado de transporte em uma memória de performance. Master, tema, brilho e banco de acordes continuam globais.</p>'''+note('Gravar uma cena não salva automaticamente o boot. Se quiser ligar o instrumento nesse estado depois, faça também um toque breve em SAVE/BT. Se PAD CHORDS estiver ativo, abrir o acesso às cenas encerra esse modo e libera suas notas e transportes.'),'Guardar')
add('volume-memoria','Volume, SAVE e memória','''<h3>Três equilíbrios diferentes</h3>'''+table(['Controle','Para que serve','Troca de cena'],[['K5 / VOL','Volume musical da cena, visível no topo de PLAY e LAYER.','Acompanha a cena carregada.'],['SYSTEM / MASTER','Redução geral da saída para o equipamento de escuta.','Permanece igual.'],['PAD CHORDS / MIX','Equilíbrio entre melodia e acordes; não substitui o volume geral.','Permanece global.']])+'''<p>Para reduzir o volume nos fones sem mudar suas cenas, ajuste MASTER. Para equilibrar presets que soam em níveis diferentes, ajuste K5 e salve cada cena. Para os acordes recuarem sob a melodia, diminua o MIX de PAD CHORDS.</p>
<h3>Como os dados são guardados</h3>'''+table(['Memória','Conteúdo','Como salvar'],[['Estado de boot','Estado musical atual, sequência, volume K5 e preferências de Master/tema/brilho.','Toque breve em SAVE/BT; a gravação ocorre ao soltar.'],['8 cenas','Oito estados musicais, sem sobrescrever as preferências globais de aparência e Master.','SAVE mantido → pad 1–8 mantido ~1 s.'],['Banco global de acordes','8 acordes, fita dos pads, MIX e PANs.','Acorde: automático ao soltar as teclas. Fita: ao selecionar. MIX/PAN: após uma breve pausa no ajuste.'],['Estado transitório','MODE Chord, HOLD e REC dos pads.','Iniciam desligados ao ligar o instrumento.']])+'''<p>Ao ligar, um SAVE válido tem prioridade sobre os valores iniciais. Sem SAVE, o ponto de partida é FLUTE, layer OFF, LOFI ativo, reverb 19%, VOL 90%, MASTER 70%, Fader Bank B, tema Light, brilho dos pads 75% e tempo 90 BPM.</p>
<p>Aguardar cerca de um segundo após ajustar MIX/PAN é suficiente para o salvamento global terminar. Caso apareça SAVE FAILED, preserve o estado atual e tente gravar novamente. Fechar a sessão de áudio USB do computador pode ser necessário para gravar dados em flash.</p>''','Guardar')
add('conexoes','USB, afinação e bateria','''<h3>MIDI por USB</h3><p>O SMKTRON recebe notas MIDI, sustain por <b>CC64</b>, modulação por <b>CC1</b> e pitch bend de aproximadamente ±2 semitons. A entrada de notas aceita os canais MIDI. PITCH e TUNE continuam influenciando a execução; as notas recebidas também podem ser usadas para capturar acordes.</p><p>O USB também permite capturar o áudio do instrumento no computador. Selecione a entrada do SMK-37 no aplicativo de áudio. Feche outras aplicações que disputem a porta MIDI quando for usar o instalador. Não confunda USB-MIDI (notas/comandos) com USB Audio (som).</p>
<h3>Bateria sempre visível</h3><p>O ícone aparece em todas as telas e estima a carga em <b>quatro níveis</b>. Nível baixo recebe destaque vermelho. Ele não mostra um percentual exato. Um contorno vazio pode indicar leitura indisponível; a conexão USB não é tratada automaticamente como confirmação de carregamento.</p>
<h3>Diagnóstico do painel</h3><p>Mantenha KNOB BANK para consultar leituras de teclas, pads, faders, rodas, ADC e informações internas. Solte para voltar à tela musical. Essa tela ajuda a descrever um controle que parece não responder; não é necessário usá-la para tocar.</p>
<h3>Instalação e recuperação</h3><p>Use o <a href="../install/">instalador do SMKTRON</a> no Chrome ou Edge de um computador, com cabo USB de dados. A página orienta a conferência do modelo, do pacote e do arquivo de retorno antes de gravar. Nenhuma atualização começa só por abrir a página ou consultar o teclado.</p><p>Para acessar a recuperação USB, mantenha OCT − pressionado ao ligar. Isso abre o modo de recuperação, sem instalar um pacote por conta própria; siga a identificação e o fluxo orientado pelo instalador.</p>''','Guardar')
add('receitas','Quatro ideias para começar','''<div class="recipes"><article><span>01 / FITA SUAVE</span><h3>Flauta com espaço</h3><p>FLUTE, TONE em torno de 65–70, ATTACK baixo, RELEASE perto de 20, WOW 15–30 e reverb entre 15–25%. Deixe DRIVE e HISS baixos.</p></article><article><span>02 / CAMADA</span><h3>Coro sob a flauta</h3><p>FLUTE principal + CHOIR no layer, MIX 25–40%, OCTAVE 0 e DETUNE 6 ct. Abra aos poucos o RELEASE. Use MODE Chord OFF para essa combinação nas mesmas teclas.</p></article><article><span>03 / ACOMPANHAMENTO</span><h3>Quatro acordes, uma melodia</h3><p>Grave C–E–G, A–C–E, F–A–C e G–B–D nos pads 1–4. Escolha CHOIR nos pads, ligue HOLD e toque uma melodia com FLUTE. Comece com MIX 35–40%.</p></article><article><span>04 / MOVIMENTO</span><h3>Violinos em sequência</h3><p>Escolha VIOLINS, grave um padrão de quatro passos, use GATE por volta de 60–80% e introduza SWING. Acrescente eco discreto e teste Leslie em SLOW.</p></article></div><p class="small">São sugestões de ponto de partida, não presets obrigatórios. Ouça o resultado e ajuste o volume para sua execução.</p>''')
add('duvidas','Dúvidas rápidas','''<div class="faq">'''+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in [
('Por que o patch parece ter só seis vozes?','Confira MODE na página PAD CHORDS. Com ON, a reserva 6 + 6 continua ativa mesmo olhando a tela PATCH. Com OFF, voltam as 12 vozes normais.'),
('A sequência está em PLAY, mas não ouço notas.','Confira se há notas gravadas no padrão e se os passos não são pausas. PLAY não cria uma sequência automaticamente. Confira também K5, Master e, com MODE Chord ON, o MIX da melodia.'),
('Por que mudar de cena altera o volume?','K5 é o volume da cena e é recuperado com ela. Use o Master global para adaptar a saída aos fones ou amplificador sem editar todas as cenas.'),
('HOLD está ligado e o acorde parou. O que conferir?','Veja LENGTH: em 8 SEC, a fita tem um limite mesmo com HOLD. Um novo pad substitui o anterior; STOP ou desligar HOLD também o libera. Abrir cenas ou trocar MODE interrompe as notas.'),
('Por que não ouço os acordes ou a melodia?','Confira MODE, se o slot tem notas, o MIX de PAD CHORDS, K5 e Master. MIX em 0% silencia os acordes; em 100%, silencia a melodia. Ouça os dois canais para avaliar PAN.'),
('Por que o acorde não grava?','Use o pad 9 REC no modo Chord, escolha um destino e solte todas as teclas ao final. O limite é seis notas distintas. SEQ REC é outro gravador. Confira a mensagem de confirmação ou de falha.'),
('Há pan, mas continuo ouvindo som nos dois lados.','Os retornos de delay/reverb e parte dos efeitos de modulação são compartilhados. Para conferir a posição do sinal direto, teste com FX inativos e com pouca textura de fita.'),
('O ruído continua com HISS em zero.','AGE também introduz ruído e desgaste. Reduza AGE/DRIVE e compare com o bypass de LOFI. O controle de ruído não funciona como um gate.'),
('Como apago um acorde?','Não existe um comando dedicado para apagar um slot individual. Você pode substituir seu conteúdo gravando outro acorde no mesmo destino.'),
('Meus acordes do simulador aparecem no teclado?','Não automaticamente. O simulador guarda dados no navegador; o instrumento guarda em sua própria memória. Grave os acordes também no teclado.'),
('Preciso salvar cada mudança imediatamente?','Acordes, fita e MIX/PAN do banco de acordes usam gravação automática. Para o estado de boot e as preferências de Master/tema/brilho, use SAVE breve. Para as oito cenas, grave o slot desejado.'),
('O pad verde pulsante é o último salvo ou o último carregado?','É o último carregado com sucesso. Salvar outro slot ou tentar carregar um slot vazio não transfere o indicador.'),
('A página do manual muda o meu instrumento?','Não. Mapas, busca, ampliação e Light/Dark aqui são recursos de consulta. Para alterar o teclado, use seus controles físicos ou o simulador conectado.')])+'''</div>''','Consultar')
add('creditos','Créditos e referência','''<p>SMKTRON: concepção, direção musical e testes por <b>Marcus Padrini</b>; adaptações de firmware e interface desenvolvidas com auxílio de ChatGPT/Codex.</p><p>Base FMEL-1 de AntonioAltea; port SMK-37 de M. Geisler (genkigenki/makkuro); Dinghy de zvenson; Felucca de Hügelton Instruments; contribuições SLOOP de isod89. Reverb adaptado do OberVave, de zvenson, a partir do algoritmo de Jon Dattorro.</p><p>Gravações de Mellotron de Bernie Kornowicz (Taijiguy), incluindo o conjunto MkII Violins. Os samples mantêm condições próprias, separadas da GPL do código, com restrição à inclusão em software comercial com fins lucrativos. Ilustrações originais de Javi; fontes Terminus/DejaVu preservam suas licenças.</p><p>As telas deste manual foram renderizadas pela própria engine do SMKTRON, com ajustes de exemplo. A captura é uma referência visual, não uma configuração que precise ser copiada. <a href="../chords-preview/source.zip">Código, licenças e documentação de origem</a>.</p><p class="small">Manual de operação para SMK-37 Pro · edição de 25 de outubro de 2026.</p>''','Consultar')
nav=''.join(f'<a href="#{id}" data-nav="{id}"><span>{i:02}</span>{title}</a>' for i,(id,title,_,_) in enumerate(sections,1))
body=''.join(f'<section class="manual-section" id="{id}" aria-labelledby="title-{id}"><p class="section-kicker">{i:02} / {group}</p><h2 id="title-{id}">{title}</h2>{content}<a class="top-link" href="#top">Voltar ao início ↑</a></section>' for i,(id,title,content,group) in enumerate(sections,1))
htmlout='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>SMKTRON — Manual de operação</title><meta name="description" content="Manual do SMKTRON para SMK-37 Pro: telas, controles, efeitos, presets, acordes, ARP e sequenciador."><link rel="stylesheet" href="manual.css?v=1"></head><body id="top"><a class="skip" href="#manual-content">Ir para o conteúdo</a><header class="masthead"><a href="#top" class="brand">SMKTRON<span>MANUAL DE OPERAÇÃO</span></a><div class="header-actions"><a href="../chords-preview/">Simulador ↗</a><button id="screen-theme" aria-pressed="false">Telas: Light</button><button id="print">Imprimir</button></div></header><div class="layout"><aside class="sidebar"><details open id="contents"><summary>Conteúdo do manual</summary><label class="search-label" for="search">BUSCAR FUNÇÃO OU CONTROLE</label><div class="search-wrap"><input id="search" type="search" placeholder="Ex.: HOLD, volume, K5…" autocomplete="off"><kbd>/</kbd></div><p id="search-status" role="status" aria-live="polite"></p><nav aria-label="Índice do manual">'''+nav+'''</nav></details><p class="sidebar-note">Use a busca para localizar funções e controles. Light/Dark alterna apenas as capturas deste manual, sem alterar o instrumento.</p></aside><main id="manual-content"><div class="hero"><div><p class="eyebrow">SMK-37 PRO / GUIA ILUSTRADO</p><h1>Conheça cada<br>lado da fita.</h1><p>Do primeiro som aos acordes nos pads. Um manual para tocar, explorar e guardar suas ideias no SMKTRON.</p><div class="hero-links"><a class="primary" href="#comecar">Começar a tocar ↓</a><a href="#chords">Ir para Pad Chords →</a></div></div>'''+shot('play','Tela PLAY do SMKTRON','Captura real da engine')+'''</div><div class="guide-note">K1–K4 seguem a tela. K5 é o volume da cena. GLOBE abre as preferências e o modo de acordes.</div><div id="no-results" hidden><h2>Nenhuma seção encontrada.</h2><p>Tente “pad”, “volume”, “MIX” ou “gravar”.</p><button id="clear-search">Limpar busca</button></div>'''+body+'''<footer class="footer"><b>SMKTRON</b><p>Uma referência para manter ao lado do instrumento.</p><a href="../chords-preview/">Abrir simulador</a> · <a href="../install/">Abrir instalador</a></footer></main></div><dialog id="screen-dialog" aria-label="Tela ampliada"><button id="close-dialog" aria-label="Fechar tela ampliada">Fechar ×</button><img width="480" height="480" alt=""><p></p></dialog><script src="manual.js?v=1" defer></script></body></html>'''
(O/'index.html').write_text(htmlout)
(O/'index.json').write_text(json.dumps([{'id':id,'title':title,'group':group} for id,title,_,group in sections],ensure_ascii=False,indent=2)+'\n')
